import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// Cooperative tiled Conv2d kernel specialized for AlexNet conv1:
//   Cin=3, KH=KW=11, stride=4, padding=2  (e.g. 224x224 -> 55x55)
//
// Structural optimization: each CTA computes an 8x16 output tile for 16
// output channels and cooperatively stages the required 3x39x71 input halo
// in shared memory once. Threads then compute all of their outputs from the
// shared input tile instead of repeatedly reloading overlapping activations
// from global memory. Register blocking: each of the 128 threads computes a
// 4x1 column of output pixels for 4 output channels (16 accumulators), so
// every weight fetched from shared memory feeds four FMAs and every input
// value feeds four FMAs. The 4x1 pixel-column mapping makes the distinct
// per-lane shared-memory column offsets within a warp stride by 4 floats
// instead of 8, so the eight addresses per warp land on eight different
// banks, removing the 2-way bank conflicts of the previous 2x2 mapping.
// The filter tile is staged transposed in shared memory (R x 16, padded
// stride 20) so every thread fetches its four per-channel weights with a
// single 16-byte float4 LDS instead of four scalar LDS, cutting shared
// load instructions in the unrolled inner loop from 8 to 5 per reduction
// step. The enlarged halo lives in dynamic shared memory with an opt-in
// max-dynamic-shared-memory-size attribute set at launch time.
template <typename T, int Cin, int KH, int KW>
__global__ void __launch_bounds__(128) conv2d_11x11_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int H, int Win,
    int Cout,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads     = 128;
  constexpr int OutTileH    = 8;
  constexpr int OutTileW    = 16;
  constexpr int CcPerBlock  = 32;
  constexpr int CPerThread  = 8;
  constexpr int ST          = 4;
  constexpr int PAD         = 2;
  constexpr int R           = Cin * KH * KW;
  constexpr int TILE_IH     = (OutTileH - 1) * ST + KH;
  constexpr int TILE_IW     = (OutTileW - 1) * ST + KW;
  constexpr int SX_LD       = 76;  // padded halo row stride (>= TILE_IW + 2, multiple of 4)
  constexpr int X_TILE_SIZE = Cin * TILE_IH * TILE_IW;
  constexpr int X_TILE_PAD  = (2 + Cin * TILE_IH * SX_LD + 3) & ~3;  // +2 column shift; keep sW 16B aligned
  constexpr int SW_LD       = CcPerBlock + 4;          // padded stride: float4-alignable, conflict-light
  constexpr int W_TILE_SIZE = R * SW_LD;               // transposed filter tile (R x CcPerBlock), padded stride
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int c_tiles = (Cout + CcPerBlock - 1) / CcPerBlock;
  const int oh_tile = blockIdx.y / c_tiles;
  const int c_tile  = blockIdx.y - oh_tile * c_tiles;
  const int ow_tile = blockIdx.x;
  const int oh0 = oh_tile * OutTileH;
  const int ow0 = ow_tile * OutTileW;
  const int c_base = c_tile * CcPerBlock;
  const int ih_base = oh0 * ST - PAD;
  const int iw_base = ow0 * ST - PAD;
  // Memory strides (NCHW contiguous)
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  // Global tensors as CuTe tensors
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Weights laid out as (Cout, Cin*KH*KW), row-major
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, R),
      make_stride(R, Int<1>{})
  );
  // Dynamic shared memory: reusable input halo + this block's filter slices
  extern __shared__ T smem_raw[];
  T* sX_raw = smem_raw;
  T* sW_raw = smem_raw + X_TILE_PAD;
  // Input halo tile: rows padded to SX_LD floats with a +2 column shift so
  // that global-float4-aligned halo columns (iw = 2 mod 4, since iw_base =
  // ow_tile*64 - 2) stay 16B-aligned in shared memory for vectorized staging.
  auto sX = make_tensor(
      make_smem_ptr(sX_raw + 2),
      make_shape(Int<Cin>{}, Int<TILE_IH>{}, Int<TILE_IW>{}),
      make_stride(Int<TILE_IH * SX_LD>{}, Int<SX_LD>{}, Int<1>{})
  );
  // Weights staged transposed (R x CcPerBlock) with padded stride SW_LD so
  // that each thread's four consecutive channel weights are contiguous and
  // 16-byte aligned, enabling a single float4 shared-memory load per step.
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<R>{}, Int<CcPerBlock>{}),
      make_stride(Int<SW_LD>{}, Int<1>{})
  );
  // Cooperative load of the input halo for this 8x16 output tile.
  // Vectorized staging: iw_base is always 2 mod 4 (ow_tile*64 - 2), so
  // global float4 loads are 16B-aligned at iw = 2 mod 4; the padded/shifted
  // sX layout keeps those same columns 16B-aligned in shared memory. Each
  // halo row is staged with 17 float4 loads plus 3 scalar head/tail loads
  // instead of 71 scalar global loads.
  constexpr int SX_VECS  = (TILE_IW - 2) / 4;  // aligned float4 groups per row
  constexpr int SX_UNITS = SX_VECS + 2;        // + head pair + tail scalar
  constexpr int SX_ROWS  = Cin * TILE_IH;
  static_assert(SX_VECS * 4 + 3 == TILE_IW,
                "vec groups + head pair + tail scalar must cover the halo row");
  if ((Win & 3) == 0) {
    for (int unit = tid; unit < SX_ROWS * SX_UNITS; unit += Threads) {
      const int row = unit / SX_UNITS;
      const int v   = unit - row * SX_UNITS;
      const int c   = row / TILE_IH;
      const int ih  = row - c * TILE_IH;
      const int gh  = ih_base + ih;
      const bool okh = ((unsigned)gh < (unsigned)H);
      if (v < SX_VECS) {
        const int iw = 2 + v * 4;
        const int gw = iw_base + iw;
        const bool full = okh && (gw >= 0) && (gw + 3 < Win);
#if __CUDA_ARCH__ >= 800
        if (full) {
          __pipeline_memcpy_async(&sX(c, ih, iw),
                                  X + (int64_t)n * sXn + (int64_t)c * sXc + (int64_t)gh * sXh + gw,
                                  sizeof(float4));
        } else
#endif
        {
          float4 val = make_float4(0.f, 0.f, 0.f, 0.f);
          if (okh) {
            val.x = ((unsigned)(gw + 0) < (unsigned)Win) ? (float)mX(c, gh, gw + 0) : 0.f;
            val.y = ((unsigned)(gw + 1) < (unsigned)Win) ? (float)mX(c, gh, gw + 1) : 0.f;
            val.z = ((unsigned)(gw + 2) < (unsigned)Win) ? (float)mX(c, gh, gw + 2) : 0.f;
            val.w = ((unsigned)(gw + 3) < (unsigned)Win) ? (float)mX(c, gh, gw + 3) : 0.f;
          }
          *reinterpret_cast<float4*>(&sX(c, ih, iw)) = val;
        }
      } else if (v == SX_VECS) {
        #pragma unroll
        for (int iw = 0; iw < 2; ++iw) {
          const int gw = iw_base + iw;
          const bool ok = okh && ((unsigned)gw < (unsigned)Win);
          sX(c, ih, iw) = ok ? mX(c, gh, gw) : T(0);
        }
      } else {
        const int iw = TILE_IW - 1;
        const int gw = iw_base + iw;
        const bool ok = okh && ((unsigned)gw < (unsigned)Win);
        sX(c, ih, iw) = ok ? mX(c, gh, gw) : T(0);
      }
    }
  } else {
    // Generic fallback for inputs whose row pitch breaks 16B alignment.
    for (int idx = tid; idx < X_TILE_SIZE; idx += Threads) {
      const int c   = idx / (TILE_IH * TILE_IW);
      const int rem = idx - c * (TILE_IH * TILE_IW);
      const int ih  = rem / TILE_IW;
      const int iw  = rem - ih * TILE_IW;
      const int gh  = ih_base + ih;
      const int gw  = iw_base + iw;
      const bool ok = ((unsigned)gh < (unsigned)H) && ((unsigned)gw < (unsigned)Win);
      sX(c, ih, iw) = ok ? mX(c, gh, gw) : T(0);
    }
  }
  // Cooperative load of weights into shared memory (transposed: R x CcPerBlock)
  for (int idx = tid; idx < W_TILE_SIZE; idx += Threads) {
    const int cl = idx / R;
    const int r  = idx - cl * R;
    const int c  = c_base + cl;
    sW(r, cl) = (c < Cout) ? mW(c, r) : T(0);  // transposed staging
  }
#if __CUDA_ARCH__ >= 800
  __pipeline_commit();
  __pipeline_wait_prior(0);
#endif
  __syncthreads();
  // Register blocking: each thread owns a 4x1 column of output pixels
  // times four output channels = 16 accumulators. All four pixels consume
  // the same shared-memory weight value, so each weight load from shared
  // memory feeds four FMAs. Because the pixel block extends along the
  // output-row direction, lanes in a warp read input columns sw0 = 4*pblk
  // apart, giving 8 distinct banks per sX load (conflict-free), while the
  // old 2x2 mapping used sw0 strides of 8 floats and hit only 4 banks.
  const int pblk = tid >> 2;          // 0..31 (4x1 pixel blocks)
  const int cgrp = tid & 3;           // 0..3
  const int p_oh = (pblk >> 4) * 4;   // 0,4
  const int p_ow = (pblk & 15);       // 0,1,...,15
  const int oh_t = oh0 + p_oh;
  const int ow_t = ow0 + p_ow;
  const int sh0 = p_oh * ST;
  const int sw0 = p_ow * ST;
  const int cw0 = cgrp * CPerThread;
  float acc[4][CPerThread];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < CPerThread; ++j) {
      const int c = c_base + cw0 + j;
      acc[i][j] = (B != nullptr && c < Cout) ? (float)B[c] : 0.0f;
    }
  }
  // Main convolution loop over the fully unrolled reduction dimension.
  int r = 0;
  #pragma unroll
  for (int c = 0; c < Cin; ++c) {
    #pragma unroll
    for (int kh = 0; kh < KH; ++kh) {
      #pragma unroll
      for (int kw = 0; kw < KW; ++kw, ++r) {
        const float xv0 = (float)sX(c, sh0 + kh,          sw0 + kw);
        const float xv1 = (float)sX(c, sh0 + kh + ST,     sw0 + kw);
        const float xv2 = (float)sX(c, sh0 + kh + 2 * ST, sw0 + kw);
        const float xv3 = (float)sX(c, sh0 + kh + 3 * ST, sw0 + kw);
        // Two 16-byte float4 LDS fetch all eight per-channel weights
        // (transposed, padded sW layout keeps both aligned + conflict-free).
        const float4 wv4a = *reinterpret_cast<const float4*>(sW_raw + r * SW_LD + cw0);
        const float4 wv4b = *reinterpret_cast<const float4*>(sW_raw + r * SW_LD + cw0 + 4);
        const float wreg[CPerThread] = {wv4a.x, wv4a.y, wv4a.z, wv4a.w,
                                        wv4b.x, wv4b.y, wv4b.z, wv4b.w};
        #pragma unroll
        for (int j = 0; j < CPerThread; ++j) {
          const float wv = wreg[j];
          acc[0][j] += xv0 * wv;
          acc[1][j] += xv1 * wv;
          acc[2][j] += xv2 * wv;
          acc[3][j] += xv3 * wv;
        }
      }
    }
  }
  // Epilogue: store results for all four register-blocked output pixels
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int oh = oh_t + i;
    const int ow = ow_t;
    if ((oh < Hout) && (ow < Wout)) {
      #pragma unroll
      for (int j = 0; j < CPerThread; ++j) {
        const int c = c_base + cw0 + j;
        if (c < Cout) {
          mY(c, oh, ow) = static_cast<T>(acc[i][j]);
        }
      }
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");
  const int64_t N   = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t H   = x.size(2);
  const int64_t Win = x.size(3);
  const int64_t Cout = w.size(0);
  TORCH_CHECK(Cin == 3, "This kernel expects Cin == 3");
  TORCH_CHECK(w.size(1) == 3 && w.size(2) == 11 && w.size(3) == 11,
              "This kernel expects weight shape [Cout, 3, 11, 11]");
  if (b.has_value()) {
    TORCH_CHECK(b.value().dim() == 1 && b.value().size(0) == Cout,
                "bias must be [Cout]");
  }
  TORCH_CHECK(stride == 4 && padding == 2,
              "This tiled kernel is specialized for stride=4, padding=2");
  const int K = 11;
  const int64_t Hout = (H + 2 * padding - K) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int Threads    = 128;
  constexpr int OutTileH   = 8;
  constexpr int OutTileW   = 16;
  constexpr int CcPerBlock = 32;
  constexpr int XTileFloats    = 2 + 3 * ((OutTileH - 1) * 4 + 11) * 76;  // padded halo rows (+2 col shift)
  constexpr int XTileFloatsPad = (XTileFloats + 3) & ~3;  // keep sW 16B aligned
  constexpr int SWld           = CcPerBlock + 4;          // padded transposed stride
  constexpr int WTileFloats    = (3 * 11 * 11) * SWld;
  constexpr int SmemBytes      = (XTileFloatsPad + WTileFloats) * (int)sizeof(float);
  const int64_t ow_tiles = (Wout + OutTileW - 1) / OutTileW;
  const int64_t oh_tiles = (Hout + OutTileH - 1) / OutTileH;
  const int64_t c_tiles  = (Cout + CcPerBlock - 1) / CcPerBlock;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)ow_tiles,
      (unsigned)(oh_tiles * c_tiles),
      (unsigned)N
  );
  static bool smem_attr_set = false;
  if (!smem_attr_set) {
    cudaFuncSetAttribute(conv2d_11x11_kernel<float, 3, 11, 11>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         SmemBytes);
    smem_attr_set = true;
  }
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_11x11_kernel<float, 3, 11, 11><<<grid, block, SmemBytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)H, (int)Win,
      (int)Cout,
      stride, padding,
      (int)Hout, (int)Wout
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_11x11_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

conv_ext = load_inline(
    name="cute_conv2d_11x11_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv2d(3 -> 96, kernel_size=11, stride=4, padding=2) implemented with a
    single custom cooperative-tiled CUDA kernel written with CuTe.
    """
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels,
                        self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

