import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// Cooperative tiled Conv2d kernel specialized for AlexNet conv1:
//   Cin=3, KH=KW=11, stride=4, padding=2  (e.g. 224x224 -> 55x55)
//
// Structural optimization: each CTA computes an 8x16 output tile for 16
// output channels and cooperatively stages the required 3x39x71 input halo
// in shared memory once. Threads then compute all of their outputs from the
// shared input tile instead of repeatedly reloading overlapping activations
// from global memory. Register blocking: each of the 128 threads computes a
// 4x1 column of output pixels for 4 output channels (16 accumulators), so
// every weight fetched from shared memory feeds four FMAs and every input
// value feeds four FMAs. The 4x1 pixel-column mapping makes the distinct
// per-lane shared-memory column offsets within a warp stride by 4 floats
// instead of 8, so the eight addresses per warp land on eight different
// banks, removing the 2-way bank conflicts of the previous 2x2 mapping.
// The filter tile is staged transposed in shared memory (R x 16, padded
// stride 20) so every thread fetches its four per-channel weights with a
// single 16-byte float4 LDS instead of four scalar LDS, cutting shared
// load instructions in the unrolled inner loop from 8 to 5 per reduction
// step. The enlarged halo lives in dynamic shared memory with an opt-in
// max-dynamic-shared-memory-size attribute set at launch time.
template <typename T, int Cin, int KH, int KW>
__global__ void __launch_bounds__(128) conv2d_11x11_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int H, int Win,
    int Cout,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads     = 128;
  constexpr int OutTileH    = 8;
  constexpr int OutTileW    = 16;
  constexpr int CcPerBlock  = 16;
  constexpr int CPerThread  = 4;
  constexpr int ST          = 4;
  constexpr int PAD         = 2;
  constexpr int R           = Cin * KH * KW;
  constexpr int TILE_IH     = (OutTileH - 1) * ST + KH;
  constexpr int TILE_IW     = (OutTileW - 1) * ST + KW;
  constexpr int SX_LD       = 76;  // padded halo row stride (>= TILE_IW + 2, multiple of 4)
  constexpr int X_TILE_SIZE = Cin * TILE_IH * TILE_IW;
  constexpr int X_TILE_PAD  = (2 + Cin * TILE_IH * SX_LD + 3) & ~3;  // +2 column shift; keep sW 16B aligned
  constexpr int SW_LD       = CcPerBlock + 4;          // padded stride: float4-alignable, conflict-light
  constexpr int W_TILE_SIZE = R * SW_LD;               // transposed filter tile (R x CcPerBlock), padded stride
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int c_tiles = (Cout + CcPerBlock - 1) / CcPerBlock;
  const int oh_tile = blockIdx.y / c_tiles;
  const int c_tile  = blockIdx.y - oh_tile * c_tiles;
  const int ow_tile = blockIdx.x;
  const int oh0 = oh_tile * OutTileH;
  const int ow0 = ow_tile * OutTileW;
  const int c_base = c_tile * CcPerBlock;
  const int ih_base = oh0 * ST - PAD;
  const int iw_base = ow0 * ST - PAD;
  // Memory strides (NCHW contiguous)
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  // Global tensors as CuTe tensors
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Weights laid out as (Cout, Cin*KH*KW), row-major
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, R),
      make_stride(R, Int<1>{})
  );
  // Dynamic shared memory: reusable input halo + this block's filter slices
  extern __shared__ T smem_raw[];
